func:
// Parse cloud connection status, debounce, manage buffering state
// Input: {cloud_connected: true/false, ts: <epoch_ms>}
// Output 1: Status/control messages to local Mosquitto
// Output 2: Replay trigger on confirmed reconnection

var data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.error('[data-buffering] ParseError: invalid cloud-connection-status payload', msg);
    return null;
}

var cloudConnected = data.cloud_connected;
if (typeof cloudConnected !== 'boolean') {
    node.warn('[data-buffering] InvalidStatus: cloud_connected is not boolean: ' + typeof cloudConnected);
    return null;
}

// Debounce: cancel any pending timer
var existingTimer = context.get('debounceTimer');
if (existingTimer) {
    clearTimeout(existingTimer);
}

var debounceMs = 3000;
var timer = setTimeout(function() {
    context.set('debounceTimer', null);
    var previousState = flow.get('cloudConnected');
    flow.set('cloudConnected', cloudConnected);
    var ts = Date.now();

    if (!cloudConnected && previousState !== false) {
        // Cloud disconnected — activate buffering
        flow.set('bufferingActive', true);
        node.warn('[data-buffering] info: Cloud disconnected \u2014 buffering mode activated');
        node.status({fill: 'yellow', shape: 'ring', text: 'buffering active'});

        node.send([{
            topic: 'nexus/internal/buffer-status',
            payload: JSON.stringify({
                buffering_active: true,
                buffer_queue_size: flow.get('bufferQueueSize') || 0,
                ts: ts
            })
        }, null]);

    } else if (cloudConnected && previousState === false) {
        // Cloud reconnected — start replay sequence
        var queueSize = flow.get('bufferQueueSize') || 0;
        node.warn('[data-buffering] info: Cloud reconnected \u2014 starting replay (' + queueSize + ' buffered)');
        node.status({fill: 'blue', shape: 'dot', text: 'replaying ' + queueSize + ' msgs'});

        // Publish pause command
        node.send([{
            topic: 'nexus/internal/telemetry-publish-control',
            payload: JSON.stringify({action: 'pause', reason: 'buffer-replay', ts: ts})
        }, null]);

        if (queueSize > 0) {
            // Trigger replay after delay (output 2)
            node.send([null, {payload: {action: 'replay', queueSize: queueSize}}]);
        } else {
            // Nothing to replay — immediately complete
            flow.set('bufferingActive', false);
            node.status({fill: 'green', shape: 'dot', text: 'connected, buffer empty'});

            node.send([{
                topic: 'nexus/internal/telemetry-publish-control',
                payload: JSON.stringify({action: 'resume', ts: ts})
            }, null]);

            node.send([{
                topic: 'nexus/internal/buffer-status',
                payload: JSON.stringify({buffering_active: false, buffer_queue_size: 0, ts: ts})
            }, null]);
        }
    }
}, debounceMs);

context.set('debounceTimer', timer);
return null;

initialize:
// Initialize buffering state on flow startup
flow.set('cloudConnected', undefined);
flow.set('bufferingActive', false);
if (!flow.get('bufferQueue')) {
    flow.set('bufferQueue', []);
}
flow.set('bufferQueueSize', (flow.get('bufferQueue') || []).length);
node.status({fill: 'grey', shape: 'ring', text: 'waiting for status'});

finalize:
// Clean up debounce timer
var timer = context.get('debounceTimer');
if (timer) {
    clearTimeout(timer);
}

func:
// Replay buffered telemetry to ThingsBoard cloud
// Output 1: Individual messages to ThingsBoard MQTT-out
// Output 2: Completion signals to local MQTT-out (resume + buffer-status)

var queue = flow.get('bufferQueue') || [];
var queueSize = queue.length;
var ts = Date.now();

if (queueSize === 0) {
    node.warn('[data-buffering] info: Replay triggered but buffer is empty');
    node.status({fill: 'green', shape: 'dot', text: 'buffer empty'});

    flow.set('bufferingActive', false);
    flow.set('bufferQueueSize', 0);

    node.send([null, {
        topic: 'nexus/internal/telemetry-publish-control',
        payload: JSON.stringify({action: 'resume', ts: ts})
    }]);
    node.send([null, {
        topic: 'nexus/internal/buffer-status',
        payload: JSON.stringify({buffering_active: false, buffer_queue_size: 0, ts: ts})
    }]);
    return null;
}

// Check cloud is still connected before replaying
if (flow.get('cloudConnected') !== true) {
    node.warn('[data-buffering] warning: Cloud disconnected during replay \u2014 aborting');
    node.status({fill: 'red', shape: 'ring', text: 'replay aborted'});
    return null;
}

node.warn('[data-buffering] info: Replaying ' + queueSize + ' buffered messages');

// Replay each message chronologically (FIFO order)
for (var i = 0; i < queue.length; i++) {
    node.send([{
        payload: queue[i],
        topic: 'v1/devices/me/telemetry'
    }, null]);
}

// Clear buffer
flow.set('bufferQueue', []);
flow.set('bufferQueueSize', 0);
flow.set('bufferingActive', false);

node.status({fill: 'green', shape: 'dot', text: 'replayed ' + queueSize + ' msgs'});
node.warn('[data-buffering] info: Replay complete \u2014 ' + queueSize + ' messages sent');

// Send resume command
node.send([null, {
    topic: 'nexus/internal/telemetry-publish-control',
    payload: JSON.stringify({action: 'resume', ts: Date.now()})
}]);

// Send completion buffer status
node.send([null, {
    topic: 'nexus/internal/buffer-status',
    payload: JSON.stringify({buffering_active: false, buffer_queue_size: 0, ts: Date.now()})
}]);

return null;

// Route telemetry: buffer when cloud disconnected, drop when connected
// telemetry-publish flow handles forwarding when cloud is connected

var MAX_BUFFER_SIZE = 10000; // Match Mosquitto max_queued_messages
var cloudConnected = flow.get('cloudConnected');

// Default to connected (don't buffer) if state unknown
if (cloudConnected !== false) {
    return null;
}

// Store in buffer (flow context array)
var queue = flow.get('bufferQueue') || [];

// Enforce max buffer size — drop oldest when full
if (queue.length >= MAX_BUFFER_SIZE) {
    queue.shift();
    node.warn('[data-buffering] BufferFull: max size ' + MAX_BUFFER_SIZE + ' reached, dropping oldest message');
}

queue.push(msg.payload);
flow.set('bufferQueue', queue);

var queueSize = queue.length;
flow.set('bufferQueueSize', queueSize);

node.status({fill: 'yellow', shape: 'ring', text: 'buffered: ' + queueSize});

// Publish buffer status every 10 messages or on first message
if (queueSize === 1 || queueSize % 10 === 0) {
    return {
        topic: 'nexus/internal/buffer-status',
        payload: JSON.stringify({
            buffering_active: true,
            buffer_queue_size: queueSize,
            ts: Date.now()
        })
    };
}

return null;

// Format error message for logging
var errorSource = msg.error ? msg.error.source : {};
var errorMsg = msg.error ? msg.error.message : 'Unknown error';
var nodeName = errorSource.name || errorSource.id || 'unknown';

node.warn('[data-buffering] ' + nodeName + ': ' + errorMsg);

msg.payload = JSON.stringify({
    ts: Date.now(),
    values: {
        db_error_count: 1,
        db_last_error: errorMsg.substring(0, 200)
    }
});
msg.topic = 'nexus/internal/data-buffering-errors';

return msg;
